const fs=require('fs'),path=require('path');
const root=process.cwd();
const readmePath=path.join(root,'README.md'),pkgPath=path.join(root,'package.json');
const readme=fs.readFileSync(readmePath,'utf8');
const pkg=JSON.parse(fs.readFileSync(pkgPath,'utf8'));
const required=['commander_start_job','commander_job_status','commander_jobs'];
const missing=required.filter(x=>!readme.includes(x));
const archive='navish-commander-'+pkg.version+'.zip';
if(!readme.includes(archive)) missing.push(archive);
const targets=[];
for(const m of readme.matchAll(/!?\[[^\]]*\]\(([^)]+)\)/g)) targets.push(m[1]);
for(const m of readme.matchAll(/^\s{0,3}\[[^\]]+\]:\s*(\S+)/gm)) targets.push(m[1]);
const bad=[];
for(let raw of targets){
 raw=raw.trim();
 if(raw.startsWith('<')&&raw.endsWith('>')) raw=raw.slice(1,-1);
 else raw=raw.split(/\s+/)[0];
 if(!raw||raw.startsWith('#')||raw.startsWith('/')||raw.startsWith('//')||/^[A-Za-z][A-Za-z0-9+.-]*:/.test(raw)) continue;
 raw=raw.split('#')[0].split('?')[0];
 if(!raw) continue;
 try{raw=decodeURIComponent(raw)}catch{}
 const p=path.resolve(path.dirname(readmePath),raw);
 if(!fs.existsSync(p)) bad.push(raw);
}
if(missing.length||bad.length){
 console.error(JSON.stringify({missing,badRelativeLinks:bad,version:pkg.version},null,2));
 process.exit(1);
}
console.log(JSON.stringify({ok:true,version:pkg.version,archive,relativeLinksChecked:targets.length},null,2));
